def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Considers (), [], {}. Other characters are ignored.
    """
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set(matching.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack

