def solve(s):
    """Convert a valid Roman numeral (I V X L C D M, subtractive notation) to an integer.

    Example: solve('IX') == 9
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        v = values[ch]
        if i + 1 < len(s) and v < values[s[i + 1]]:
            total -= v
        else:
            total += v
    return total

def solve(intervals):
    """Merge overlapping or touching [start, end] intervals; return sorted by start.

    Example: solve([[1, 3], [2, 6], [8, 10]]) == [[1, 6], [8, 10]]
    """
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = [list(ordered[0])]
    for start, end in ordered[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

