def solve(tokens):
    """Evaluate Reverse Polish Notation.
    tokens: list of strings, each token is an integer or one of '+', '-', '*', '/'.
    Returns the integer result, with division truncating toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division truncating toward zero
                # Using int(a / b) gives trunc toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

