def solve(grid):
    """Count islands of 1s in a grid of 0s and 1s (4-directional connectivity).

    Handles jagged grids where rows may have different lengths.

    Example: solve([[1, 1, 0], [0, 1, 0], [0, 0, 1]]) == 2
    """
    if not grid:
        return 0
    rows = len(grid)
    seen = [set() for _ in range(rows)]
    count = 0
    for r in range(rows):
        row_len = len(grid[r])
        for c in range(row_len):
            if grid[r][c] == 1 and c not in seen[r]:
                count += 1
                stack = [(r, c)]
                seen[r].add(c)
                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < rows and 0 <= ny < len(grid[nx])
                                and grid[nx][ny] == 1 and ny not in seen[nx]):
                            seen[nx].add(ny)
                            stack.append((nx, ny))
    return count

