def solve(nums):
    """Return the length of the longest strictly increasing subsequence of nums.

    Example: solve([10, 9, 2, 5, 3, 7, 101, 18]) == 4
    """
    if not nums:
        return 0
    tails = []  # tails[k] = smallest tail of an increasing subsequence of length k + 1
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
