    """Count islands in a possibly jagged grid of 0/1.
    Cells are adjacent orthogonally. Handles rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def neighbors(r,c):
        # up
        if r-1 >= 0 and c < len(grid[r-1]):
            yield r-1, c
        # down
        if r+1 < rows and c < len(grid[r+1]):
            yield r+1, c
        # left
        if c-1 >= 0:
            yield r, c-1
        # right
        if c+1 < len(grid[r]):
            yield r, c+1
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for nx,ny in neighbors(x,y):
                if not visited[nx][ny] and grid[nx][ny]==1:
                    stack.append((nx,ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count += 1
    return count"}

