def solve(tokens):
    """Evaluate Reverse Polish Notation.
    tokens: list of strings, each either an integer literal or '+', '-', '*', '/'.
    Division truncates toward zero.
    Returns integer result.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

